import torch
import torch.nn.functional as F

def greedy_decode(logits):
    return torch.argmax(logits, dim=-1)

def temperature_sample(logits, temperature=1.0):
    probs = F.softmax(logits / temperature, dim=-1)
    return torch.multinomial(probs, num_samples=1).squeeze(-1)

def top_k_sample(logits, k=50, temperature=1.0):
    logits = logits / temperature
    topk_vals, topk_idx = torch.topk(logits, k, dim=-1)
    probs = F.softmax(topk_vals, dim=-1)
    sampled = torch.multinomial(probs, num_samples=1)
    return topk_idx.gather(-1, sampled).squeeze(-1)

def top_p_sample(logits, p=0.9, temperature=1.0):
    logits = logits / temperature
    sorted_logits, sorted_idx = torch.sort(logits, descending=True, dim=-1)
    sorted_probs = F.softmax(sorted_logits, dim=-1)
    cumulative = torch.cumsum(sorted_probs, dim=-1)

    # remove tokens once cumulative probability exceeds p (keep at least 1 token)
    remove_mask = cumulative - sorted_probs > p
    sorted_logits[remove_mask] = float("-inf")

    probs = F.softmax(sorted_logits, dim=-1)
    sampled = torch.multinomial(probs, num_samples=1)
    return sorted_idx.gather(-1, sampled).squeeze(-1)


def generate(model, input_ids, max_new_tokens, method="top_p", **kwargs):
    for _ in range(max_new_tokens):
        logits = model(input_ids)[:, -1, :]  # last-position logits
        if method == "greedy":
            next_token = greedy_decode(logits)
        elif method == "temperature":
            next_token = temperature_sample(logits, **kwargs)
        elif method == "top_k":
            next_token = top_k_sample(logits, **kwargs)
        elif method == "top_p":
            next_token = top_p_sample(logits, **kwargs)
        input_ids = torch.cat([input_ids, next_token.unsqueeze(-1)], dim=-1)
    return input_ids

