import torch
import torch.nn as nn

class IA3ScaledLinear(nn.Module):
    """Wraps a frozen nn.Linear and multiplies its OUTPUT by a learned per-channel vector.
    Used for scaling key/value projections and FFN intermediate activations."""
    def __init__(self, base_linear: nn.Linear):
        super().__init__()
        self.base = base_linear
        for p in self.base.parameters():
            p.requires_grad = False
        out_features = base_linear.out_features
        self.ia3_vector = nn.Parameter(torch.ones(out_features))  # init at 1 -> no effect initially

    def forward(self, x):
        out = self.base(x)
        return out * self.ia3_vector  # element-wise rescaling of each output channel


def inject_ia3(model, target_names=("k_proj", "v_proj", "ffn_up")):
    for p in model.parameters():
        p.requires_grad = False
    for module in model.modules():
        for child_name, child in list(module.named_children()):
            if child_name in target_names and isinstance(child, nn.Linear):
                setattr(module, child_name, IA3ScaledLinear(child))
    return model


if __name__ == "__main__":
    layer = nn.Linear(32, 32)
    ia3_layer = IA3ScaledLinear(layer)
    x = torch.randn(4, 32)
    out = ia3_layer(x)
    print(out.shape)
    trainable = sum(p.numel() for p in ia3_layer.parameters() if p.requires_grad)
    print(f"trainable params (just the scaling vector): {trainable}")

import json
import re

tools = [
    {
        "name": "get_weather",
        "description": "Get the current weather for a city",
        "parameters": {"city": "string"},
    },
    {
        "name": "calculator",
        "description": "Evaluate a basic arithmetic expression",
        "parameters": {"expression": "string"},
    },
]

def build_system_prompt(tools):
    tool_descriptions = json.dumps(tools, indent=2)
    return (
        "You are an assistant with access to these tools:\n"
        f"{tool_descriptions}\n"
        "To call a tool, respond with EXACTLY this format and nothing else:\n"
        '<tool_call>{"name": "<tool_name>", "arguments": {...}}</tool_call>\n'
        "Otherwise, respond normally to the user."
    )

def parse_tool_call(model_output: str):
    match = re.search(r"<tool_call>(.*?)</tool_call>", model_output, re.DOTALL)
    if not match:
        return None
    return json.loads(match.group(1))

def execute_tool(call):
    name, args = call["name"], call["arguments"]
    if name == "get_weather":
        return f"The weather in {args['city']} is sunny, 22C."  # stub / mock implementation
    if name == "calculator":
        return str(eval(args["expression"], {"__builtins__": {}}))
    return f"Unknown tool: {name}"

def run_agent_turn(model_generate_fn, conversation):
    """model_generate_fn: a function(prompt: str) -> str representing one LLM call."""
    system_prompt = build_system_prompt(tools)
    prompt = system_prompt + "\n\n" + conversation

    model_output = model_generate_fn(prompt)
    call = parse_tool_call(model_output)

    if call is not None:
        tool_result = execute_tool(call)
        conversation += f"\nAssistant (tool call): {model_output}"
        conversation += f"\nTool result: {tool_result}"
        final_output = model_generate_fn(system_prompt + "\n\n" + conversation)
        return final_output

    return model_output

